task min_coins(coins: seq, value: int, min_coins_count: int) returns (r: int)
  requires value >= 0
  requires min_coins_count >= 0
  ensures r == min_coins_count
  ensures r >= 0
  ensures value == 0 ==> r == 0
  ensures value > 0 ==> r > 0
  ensures forall c in coins, c > 0
  ensures r == [0..r-1] | [c in coins, c <= value] ==> value == sum([0..r-1] | [c in coins, c <= value])
{
  if value == 0 {
    r := 0;
  } else {
    var min: int := value + 1;
    var count: int := 0;
    var i: int := 0;
    while i < len(coins) and min > 0
      invariant 0 <= i and i <= len(coins)
      invariant min >= 0
      invariant count >= 0
      invariant value == sum([0..i-1] | [c in coins, c <= value]) + min * count
      decreases len(coins) - i
    {
      if coins[i] <= value {
        var new_min: int := value - coins[i] + 1;
        if new_min < min {
          min := new_min;
          count := count + 1;
        }
      }
      i := i + 1;
    }
    r := count;
  }
}
